    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\nclass TreeNode:\n    def __init__(self, val=0, left=None, right=None):\n        self.val = val\n        self.left = left\n        self.right = right\n\ndef _tree_build(vals):\n    if not vals or vals[0] is None:\n        return None\n    root = TreeNode(vals[0])\n    q = [root]\n    i = 1\n    while q and i < len(vals):\n        node = q.pop(0)\n        if i < len(vals) and vals[i] is not None:\n            node.left = TreeNode(vals[i])\n            q.append(node.left)\n        i += 1\n        if i < len(vals) and vals[i] is not None:\n            node.right = TreeNode(vals[i])\n            q.append(node.right)\n        i += 1\n    return root\n\ndef _tree_show(root):\n    if not root:\n        return []\n    out = []\n    q = [root]\n    while q:\n        node = q.pop(0)\n        out.append(node.val if node else None)\n        if node:\n            q.append(node.left)\n            q.append(node.right)\n    while out and out[-1] is None:\n        out.pop()\n    return out\n\ndef _tree_array_build(arr):\n    return [_tree_build(x) for x in arr]\n\ndef _tree_array_show(arr):\n    return [_tree_show(x) for x in arr]\n\n# \u9012\u5f52\u6cd5\uff1a\nclass Solution:\n    def countNodes(self, root: TreeNode) -> int:\n        return self.getNodesNum(root)\n        \n    def getNodesNum(self, cur):\n        if not cur:\n            return 0\n        leftNum = self.getNodesNum(cur.left) #\u5de6\n        rightNum = self.getNodesNum(cur.right) #\u53f3\n        treeNum = leftNum + rightNum + 1 #\u4e2d\n        return treeNum\n\n# \u9012\u5f52\u6cd5\uff1a\u7cbe\u7b80\u7248\nclass Solution:\n    def countNodes(self, root: TreeNode) -> int:\n        if not root:\n            return 0\n        return 1 + self.countNodes(root.left) + self.countNodes(root.right)\n\n# \u8fed\u4ee3\u6cd5\uff1a\nimport collections\nclass Solution:\n    def countNodes(self, root: TreeNode) -> int:\n        queue = collections.deque()\n        if root:\n            queue.append(root)\n        result = 0\n        while queue:\n            size = len(queue)\n            for i in range(size):\n                node = queue.popleft()\n                result += 1 #\u8bb0\u5f55\u8282\u70b9\u6570\u91cf\n                if node.left:\n                    queue.append(node.left)\n                if node.right:\n                    queue.append(node.right)\n        return result\n\n# \u5b8c\u5168\u4e8c\u53c9\u6811\nclass Solution:\n    def countNodes(self, root: TreeNode) -> int:\n        if not root:\n            return 0\n        left = root.left\n        right = root.right\n        leftDepth = 0 #\u8fd9\u91cc\u521d\u59cb\u4e3a0\u662f\u6709\u76ee\u7684\u7684\uff0c\u4e3a\u4e86\u4e0b\u9762\u6c42\u6307\u6570\u65b9\u4fbf\n        rightDepth = 0\n        while left: #\u6c42\u5de6\u5b50\u6811\u6df1\u5ea6\n            left = left.left\n            leftDepth += 1\n        while right: #\u6c42\u53f3\u5b50\u6811\u6df1\u5ea6\n            right = right.right\n            rightDepth += 1\n        if leftDepth == rightDepth:\n            return (2 << leftDepth) - 1 #\u6ce8\u610f(2<<1) \u76f8\u5f53\u4e8e2^2\uff0c\u6240\u4ee5leftDepth\u521d\u59cb\u4e3a0\n        return self.countNodes(root.left) + self.countNodes(root.right) + 1\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n    _args[0] = _tree_build(_args[0])\n    _ret = _sol.countNodes(_args[0])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
