    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\nclass TreeNode:\n    def __init__(self, val=0, left=None, right=None):\n        self.val = val\n        self.left = left\n        self.right = right\n\ndef _tree_build(vals):\n    if not vals or vals[0] is None:\n        return None\n    root = TreeNode(vals[0])\n    q = [root]\n    i = 1\n    while q and i < len(vals):\n        node = q.pop(0)\n        if i < len(vals) and vals[i] is not None:\n            node.left = TreeNode(vals[i])\n            q.append(node.left)\n        i += 1\n        if i < len(vals) and vals[i] is not None:\n            node.right = TreeNode(vals[i])\n            q.append(node.right)\n        i += 1\n    return root\n\ndef _tree_show(root):\n    if not root:\n        return []\n    out = []\n    q = [root]\n    while q:\n        node = q.pop(0)\n        out.append(node.val if node else None)\n        if node:\n            q.append(node.left)\n            q.append(node.right)\n    while out and out[-1] is None:\n        out.pop()\n    return out\n\ndef _tree_array_build(arr):\n    return [_tree_build(x) for x in arr]\n\ndef _tree_array_show(arr):\n    return [_tree_show(x) for x in arr]\n\nclass Solution:\n    def reverseOddLevels(self, root: Optional[TreeNode]) -> Optional[TreeNode]:\n        q = [root]\n        isOdd = False\n        while len(q) > 0:\n            if isOdd:\n                for i in range (len(q) // 2):\n                    nodex, nodey = q[i], q[len(q) - 1 - i]\n                    nodex.val, nodey.val = nodey.val, nodex.val\n            tmp = q\n            q = []\n            for node in tmp:\n                if node.left is not None:\n                    q.append(node.left)\n                    q.append(node.right)                           \n            isOdd ^= True\n        return root\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n    _args[0] = _tree_build(_args[0])\n    _ret = _sol.reverseOddLevels(_args[0])\n    _out = json.dumps(_tree_show(_ret), separators=(',', ':'))\n    sys.stdout.write(_out)\n\nmain()\n",
